/**
 * Full walk-forward validation report. Contains config echo, per-window results, overall metrics for the three model variants (base/layered/ full), layer comparison, six benchmarks, confidence calibration, recommendation outcome analysis, stability analysis, verdict, cost breakdown, equity and drawdown curves, and the lookahead audit.
 */
export interface WalkForwardResult {
  available: boolean;
  generated_at?: string;
  run_seconds?: number;
  config?: WalkForwardResultConfig;
  intrabar_rule_label?: string;
  universe_size?: number;
  skipped_symbols?: string[];
  adaptive_model_version?: number;
  knowledge_trades_available?: number;
  similarity_vectors_available?: number;
  windows?: WalkForwardResultWindowsItem[];
  overall?: WalkForwardResultOverall;
  layer_comparison?: WalkForwardResultLayerComparisonItem[];
  /** Phase 2A analysis report (analysis only — the live pipeline is unchanged): corrected gated ranking + edge-proportional allocation evaluated as walk-forward variants D (default gates) and E (strict gates) against the preserved legacy policy (variant C). Includes the C/D/E comparison, rejected-trade diagnostics (with would-be outcomes computed after the fact — never fed back into decisions) and a deployment recommendation. */
  phase2a?: WalkForwardResultPhase2a;
  /** Phase 2B strategy audit report (ANALYSIS ONLY — the ranking engine and live pipeline are unchanged). Per-strategy scorecards with 8 performance breakdowns, entry-condition diagnostics, exit-rule alternatives A–G replayed on identical entries, loss attribution, holding-period analysis, per-regime eligibility, cost sensitivity, robustness checks, up to 3 entry-variant configurations per strategy (train-selected, test-evaluated), model comparison A–F and a final report answering the audit questions. If the audit step failed, the object contains only an "error" string instead. */
  strategy_audit?: WalkForwardResultStrategyAudit;
  /** Phase 3 MACD optimization report (ANALYSIS ONLY — the live pipeline is unchanged). Entry filters, exit variations and portfolio risk rules for MACD Cross, each tested independently with parameters selected on training windows and evaluated only on unseen test windows. Includes baseline metrics (trade-level and portfolio), a full comparison table with per-variation verdicts and reasons, the combined configuration's out-of-sample results and the final recommended configuration. If the step failed, the object contains only an "error" string instead. */
  macd_optimization?: WalkForwardResultMacdOptimization;
  benchmarks?: WalkForwardResultBenchmarks;
  /** Phase 5 Alpha Generation Engine (ANALYSIS ONLY — never changes live decisions). Evaluates 10 new strategy candidates formed by layering additional entry filters onto MACD Cross OOS trades. Filters include multi-timeframe trend (ADX), relative strength vs NIFTY 50, VWAP/volume participation, ATR volatility, market-regime selection, sector focus, holding-period limits, and multi-signal intersections. Each candidate receives a KEEP_FOR_FURTHER_TESTING / INCONCLUSIVE / REJECT verdict based on 6 quality gates: positive expectancy, PF ≥ 1.10, ≥ 30 trades, ≥ 50% windows positive, max drawdown < 60%, top-5 trade share ≤ 70% of gross profit. */
  alpha_generation?: WalkForwardResultAlphaGeneration;
  /** Phase 3A Balanced Decision Model (ANALYSIS ONLY — never changes live decisions). A shadow scoring model "G" replayed over the identical walk-forward windows: hard eligibility gates separated from a 0-100 weighted ranking score (technical 30 / opportunity 20 / historical evidence 15 / adaptive learning 10 / regime 10 / risk-reward 10 / volume 5), Bayesian-shrunk learning adjustments capped at ±10/±10 (combined ±15), per-window confidence calibration, shadow labels (STRONG BUY/BUY/WATCH/AVOID/ NO TRADE), A-G model comparison, decision transition matrix, lookahead audit and an evidence-based REJECT / CONTINUE ANALYSIS / ELIGIBLE FOR LIMITED SHADOW PAPER TEST verdict that never auto-activates anything. */
  balanced_decision?: WalkForwardResultBalancedDecision;
  /** Phase 4 MACD Robustness Analysis (ANALYSIS ONLY — never changes live decisions). Measures structural soundness via 8 breakdowns (by stock, sector, month, regime, holding period, volatility, ADX, entry subtype), 5 stress tests (leave-one-stock/sector/month out, top-5-trades removed, winsorized returns), and issues a conservative KEEP / RESTRICT / REJECT stability verdict with explicit pass/fail checks, regime-specific enable/disable recommendations and a prioritised improvement roadmap. */
  macd_robustness?: WalkForwardResultMacdRobustness;
  calibration?: WalkForwardResultCalibrationItem[];
  /** Phase 1 confidence-calibration report for the full model: before (raw confidence / 100) vs after (per-window calibrated probability) Brier score, ECE and log loss, reliability-diagram bins for both, per-window calibrator metadata (method, training samples, version) and the calibrated-probability execution floor. */
  calibration_report?: WalkForwardResultCalibrationReport;
  /** Phase 2 adaptive strategy selection report: per-strategy performance matrix (overall and per market regime), strategy ranking with enable/disable decisions and human-readable reasons for the current regime, dynamic allocation weights, and per-window snapshots. Learned only from completed out-of-sample trades (no lookahead). */
  strategy_intelligence?: WalkForwardResultStrategyIntelligence;
  recommendation_outcomes?: WalkForwardResultRecommendationOutcomesItem[];
  recommendations_issued?: number;
  stability?: WalkForwardResultStability;
  verdict?: WalkForwardResultVerdict;
  cost_breakdown?: WalkForwardResultCostBreakdown;
  equity_curve?: WalkForwardResultEquityCurveItem[];
  drawdown_curve?: WalkForwardResultDrawdownCurveItem[];
  lookahead_audit?: WalkForwardResultLookaheadAudit;
  safety?: string;
  [key: string]: unknown;
 }

